const rows = $input.all().map(i => i.json).filter(r => r.item_id);
const profile = {};
for (const r of rows) if (r.section === 'profile') profile[String(r.item_id).replace(/^PR_/, '')] = r.text || '';
const master = rows.filter(r => r.section !== 'profile').map(r => ({
  id: r.item_id,
  section: r.section,
  parent: r.parent || '',
  text: r.text || '',
  dates: r.dates || '',
  tags: r.tags || '',
  org: r.org || '',
  place: r.place || '',
  role: r.role || ''
}));
return [{ json: { master, profile, count: master.length } }];

const raw = String($input.first().json.text || '');
const master = $('Pack master CV').first().json.master;
const byId = {};
for (const r of master) byId[r.id] = r;
const idsOf = section => master.filter(r => r.section === section).map(r => r.id);
const problems = [];

// 1) Parse the model's answer (first "{" to last "}")
let sel = {};
const s = raw.indexOf('{');
const e = raw.lastIndexOf('}');
if (s >= 0 && e > s) {
  try { sel = JSON.parse(raw.slice(s, e + 1)); }
  catch (err) { problems.push('answer is not valid JSON'); }
} else {
  problems.push('no JSON in answer');
}

const isId = (id, section) => typeof id === 'string' && byId[id] && byId[id].section === section;
const uniq = a => [...new Set(Array.isArray(a) ? a : [])];

// Keep valid ids, then top up from `pool` until we have n
function pick(list, section, n, pool, label) {
  const all = uniq(list);
  const good = all.filter(id => isId(id, section));
  if (good.length < all.length) problems.push(label + ': invalid id removed');
  const out = good.slice(0, n);
  for (const id of pool) {
    if (out.length >= n) break;
    if (!out.includes(id)) { out.push(id); problems.push(label + ': topped up with ' + id); }
  }
  return out;
}

// 2) Experiences: 3 roles, 3 / 2 / 1 bullets
const rawExp = Array.isArray(sel.exp) ? sel.exp : [];
const roles = pick(rawExp.map(x => x && x.role), 'experience', 3, idsOf('experience'), 'roles');
const sizes = [3, 2, 1];
const exp = roles.map((role, i) => {
  const given = rawExp.find(x => x && x.role === role);
  const own = master.filter(r => r.section === 'experience_bullet' && r.parent === role).map(r => r.id);
  const wanted = Array.isArray(given && given.bullets) ? given.bullets.filter(b => byId[b] && byId[b].parent === role) : [];
  const bullets = pick(wanted, 'experience_bullet', sizes[i], own, 'bullets of ' + role);
  if (bullets.length < sizes[i]) problems.push(role + ': only ' + bullets.length + ' bullets available');
  return { role, bullets };
});

// 3) Projects: 2 projects, 1 bullet each
const rawProj = Array.isArray(sel.projects) ? sel.projects : [];
const projIds = pick(rawProj.map(x => x && x.project), 'project', 2, idsOf('project'), 'projects');
const projects = projIds.map(p => {
  const given = rawProj.find(x => x && x.project === p);
  const own = master.filter(r => r.section === 'project_bullet' && r.parent === p).map(r => r.id);
  const bullet = given && own.includes(given.bullet) ? given.bullet : own[0];
  return { project: p, bullet };
});

// 4) Clubs, coursework, skills
const clubs = pick(sel.clubs, 'club', 2, idsOf('club'), 'clubs');
let coursework = pick(sel.coursework, 'coursework', 8, [], 'coursework');
if (coursework.length < 3) problems.push('coursework: fewer than 3');
const skills = pick(sel.skills, 'skill', 3, idsOf('skill'), 'skills');
// Education: ED1 (main degree) is always shown; the model may add 0 to 3 more entries
// (no top-up: someone with no summer school simply gets fewer). Shown in the master's row order.
const order = master.map(r => r.id);
const eduPicked = pick(uniq(sel.education).filter(id => id !== 'ED1'), 'education', 3, [], 'education');
// Top up to at least 2 extra education entries (entries with bullets first, then master order), so the page is not left half empty
const hasBullet = id => master.some(r => r.section === 'education_bullet' && r.parent === id);
const eduPool = master.filter(r => r.section === 'education' && r.id !== 'ED1').map(r => r.id)
  .map((id, i) => ({ id, i })).sort((a, b) => (hasBullet(b.id) ? 1 : 0) - (hasBullet(a.id) ? 1 : 0) || a.i - b.i).map(x => x.id);
for (const id of eduPool) { if (eduPicked.length >= 2) break; if (!eduPicked.includes(id)) eduPicked.push(id); }
const eduExtra = eduPicked.sort((a, b) => order.indexOf(a) - order.indexOf(b));

// 5) Summary: length, numbers and claims must come from the master CV
const FALLBACK = 'Engineering and management double-degree student with hands-on experience in Python, data analysis and financial markets.';
let summary = typeof sel.summary === 'string' ? sel.summary.trim() : '';
if (summary.length > 260) {
  // keep the whole sentences that fit; if not even the first one fits, the fallback below applies
  const parts = summary.match(/[^.!?]+[.!?]+/g) || [];
  let cut = '';
  for (const p of parts) { if ((cut + p).trim().length <= 260) cut = (cut + p).trim() + ' '; else break; }
  if (cut.trim()) { summary = cut.trim(); problems.push('summary shortened to whole sentences'); }
}
const allText = master.map(r => r.text + ' ' + (r.dates || '')).join(' ');
const numbers = (summary.match(/\d[\d.,%]*/g) || []).map(n => n.replace(/[.,]+$/, ''));
// claim verbs that must appear in the master CV itself to be used in the summary
const claimVerbs = ['validated', 'validation', 'led', 'managed', 'headed', 'founded', 'spearheaded', 'directed', 'oversaw', 'supervised', 'deployed', 'taught', 'mentored', 'coached', 'lectured'];
const allLow = allText.toLowerCase();
const badVerbs = claimVerbs.filter(v => { const re = new RegExp('\\b' + v + '\\b', 'i'); return re.test(summary) && !re.test(allLow); });
let summaryBad = false;
if (!summary) { summaryBad = true; problems.push('summary missing'); }
else if (summary.length > 260) { summaryBad = true; problems.push('summary too long'); }
else if (numbers.some(n => !allText.includes(n))) { summaryBad = true; problems.push('summary has a number not in the master CV'); }
else if (badVerbs.length) { summaryBad = true; problems.push('summary claims something not in the master CV: ' + badVerbs.join(', ')); }
if (summaryBad) summary = FALLBACK;

// 6) Build the slot values (ids -> texts)
const t = id => (byId[id] ? String(byId[id].text || '') : '');
const f = (id, k) => (byId[id] && byId[id][k] ? String(byId[id][k]) : '');
// Entry header: org / place / role / dates (falls back to the full text if org is empty)
function header(slots, prefix, id) {
  const org = f(id, 'org');
  slots[prefix + '_org'] = org || t(id);
  slots[prefix + '_place'] = org ? f(id, 'place') : '';
  slots[prefix + '_role'] = org ? f(id, 'role') : '';
  slots[prefix + '_dates'] = f(id, 'dates');
}
// A bullet slot carries its own bullet and tab, so an empty slot never leaves a lone dot
const bl = x => (x ? '•\t' + x : '');
const firstBullet = id => { const b = master.find(r => r.section === 'education_bullet' && r.parent === id); return b ? String(b.text) : ''; };
// "Label: text" -> label + text
function labelled(slots, prefix, id) {
  const x = t(id), i = x.indexOf(':');
  slots[prefix + '_label'] = i > 0 ? x.slice(0, i).trim() : '';
  slots[prefix + '_text'] = i > 0 ? x.slice(i + 1).trim() : x;
}

const slots = { summary };
for (const [n, k] of [[1, 3], [2, 2], [3, 1]]) {
  for (const key of ['org', 'place', 'role', 'dates']) slots['exp' + n + '_' + key] = '';
  for (let j = 1; j <= k; j++) slots['exp' + n + '_b' + j] = '';
}
for (let n = 1; n <= 4; n++) { for (const key of ['org', 'place', 'role', 'dates']) slots['edu' + n + '_' + key] = ''; slots['edu' + n + '_b1'] = ''; }
exp.forEach((x, i) => {
  const n = i + 1;
  header(slots, 'exp' + n, x.role);
  x.bullets.forEach((b, j) => { slots['exp' + n + '_b' + (j + 1)] = bl(t(b)); });
});
projects.forEach((x, i) => {
  const n = i + 1;
  header(slots, 'proj' + n, x.project);
  slots['proj' + n + '_b1'] = bl(t(x.bullet));
});
clubs.forEach((c, i) => { slots['extra_' + (i + 1)] = bl(t(c)); });
while (coursework.map(t).join(', ').length > 220 && coursework.length > 1) coursework.pop();
slots.coursework = coursework.map(t).join(', ');
skills.forEach((k, i) => labelled(slots, 'skills_' + (i + 1), k));
header(slots, 'edu1', 'ED1');
slots.edu1_b1 = bl(firstBullet('ED1'));
eduExtra.forEach((id, i) => { const n = i + 2; header(slots, 'edu' + n, id); slots['edu' + n + '_b1'] = bl(firstBullet(id)); });
labelled(slots, 'languages', 'F1');
labelled(slots, 'certifications', 'F2');
labelled(slots, 'interests', 'F3');

// 7) Unused parts of the template: every paragraph that contains this marker
//    will be deleted when the Google Doc is filled
const DEL = '§§DEL§§';
// 6b) One-page guard: estimate the lines the CV takes and trim the least valuable content until it fits
const wrap = (txt, w) => { const x = String(txt || '').replace(/^•\t/, ''); return x ? Math.max(1, Math.ceil(x.length / w)) : 0; };
const estimate = () => {
  let n = wrap(slots.summary, 115);
  for (const p of ['exp1', 'exp2', 'exp3', 'proj1', 'proj2', 'edu1', 'edu2', 'edu3', 'edu4']) if (slots[p + '_org']) n += 2;
  for (const k of Object.keys(slots)) if (/_b\d$|^extra_\d$/.test(k)) n += wrap(slots[k], 104);
  n += wrap('Relevant coursework: ' + slots.coursework, 104);
  for (let i = 1; i <= 3; i++) n += wrap((slots['skills_' + i + '_label'] || '') + ': ' + (slots['skills_' + i + '_text'] || ''), 112);
  return n + 3;   // languages, certifications, interests
};
const LINE_BUDGET = 43;
const trims = [
  () => { if (coursework.length > 4) { coursework.pop(); slots.coursework = coursework.map(t).join(', '); return true; } return false; },
  () => { for (const n of [4, 3, 2]) if (slots['edu' + n + '_b1']) { slots['edu' + n + '_b1'] = ''; return true; } return false; },
  () => { if (slots.exp1_b3) { slots.exp1_b3 = ''; return true; } return false; },
  () => { if (slots.extra_2) { slots.extra_2 = ''; return true; } return false; },
  () => { if (coursework.length > 2) { coursework.pop(); slots.coursework = coursework.map(t).join(', '); return true; } return false; },
  () => { if (slots.exp2_b2) { slots.exp2_b2 = ''; return true; } return false; },
];
let guard = 0;
while (estimate() > LINE_BUDGET && guard++ < 12) { if (!trims.some(f => f())) break; }
for (const k of Object.keys(slots)) {
  if (/_b\d$|^extra_\d$/.test(k) && !slots[k]) slots[k] = DEL;
}
for (const p of ['exp1', 'exp2', 'exp3', 'proj1', 'proj2', 'edu1', 'edu2', 'edu3', 'edu4']) {
  if (!slots[p + '_org']) for (const key of ['org', 'place', 'role', 'dates']) slots[p + '_' + key] = DEL;
}

return [{ json: {
  selection_ok: problems.length === 0,
  problems,
  gaps: Array.isArray(sel.gaps) ? sel.gaps.map(String).slice(0, 6) : [],
  ids: { roles, exp, projects, clubs, coursework, skills, education: eduExtra },
  slots
} }];

const v = $input.first().json;
const p = $('Pack master CV').first().json;
return [{ json: { ok: true, selection_ok: v.selection_ok, problems: v.problems, gaps: v.gaps, ids: v.ids, slots: v.slots, profile: p.profile, master: p.master } }];
